package java.nio;
public abstract class Buffer { protected int position,limit,capacity,mark=-1; protected Buffer(int capacity){this.capacity=capacity;limit=capacity;} public final int capacity(){return capacity;} public final int position(){return position;} public Buffer position(int n){if(n<0||n>limit)throw new IllegalArgumentException();position=n;if(mark>n)mark=-1;return this;} public final int limit(){return limit;} public Buffer limit(int n){if(n<0||n>capacity)throw new IllegalArgumentException();limit=n;if(position>n)position=n;if(mark>n)mark=-1;return this;} public Buffer mark(){mark=position;return this;} public Buffer reset(){if(mark<0)throw new IllegalStateException();position=mark;return this;} public Buffer clear(){position=0;limit=capacity;mark=-1;return this;} public Buffer flip(){limit=position;position=0;mark=-1;return this;} public Buffer rewind(){position=0;mark=-1;return this;} public final int remaining(){return limit-position;} public final boolean hasRemaining(){return position<limit;} public abstract boolean isReadOnly(); public abstract boolean isDirect(); }
